CREATE TABLE IF NOT EXISTS operational_requests(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id),requester_id TEXT NOT NULL REFERENCES users(id),requester_name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('purchase','expense','asset_loan','administration','activity_permission')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',amount BIGINT NOT NULL DEFAULT 0 CHECK(amount>=0 AND amount<=1000000000000),fund TEXT NOT NULL DEFAULT 'Organisasi' CHECK(fund IN ('Organisasi','Program','Usaha')),asset_id TEXT REFERENCES records(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0 AND quantity<=1000000),desired_date TEXT NOT NULL DEFAULT '',end_date TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','revision','approved','rejected','cancelled','in_progress','completed')),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),last_event_id TEXT NOT NULL,cash_record_id TEXT REFERENCES records(id),proof_id TEXT,proof_name TEXT,proof_mime TEXT,created TEXT NOT NULL,updated TEXT NOT NULL,UNIQUE(owner,cash_record_id));
CREATE INDEX IF NOT EXISTS operational_requests_owner_requester ON operational_requests(owner,requester_id,updated);
CREATE INDEX IF NOT EXISTS operational_requests_owner_status ON operational_requests(owner,status,category);
CREATE INDEX IF NOT EXISTS operational_requests_asset_status ON operational_requests(asset_id,status);
CREATE TABLE IF NOT EXISTS operational_events(id TEXT PRIMARY KEY,owner TEXT NOT NULL,request_id TEXT NOT NULL REFERENCES operational_requests(id),version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),actor_name TEXT NOT NULL,action TEXT NOT NULL,from_status TEXT NOT NULL,to_status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created TEXT NOT NULL,UNIQUE(request_id,version));
CREATE INDEX IF NOT EXISTS operational_events_request ON operational_events(owner,request_id,version);
